import '@gravity-ui/yagr/index.css';

import {useEffect, useMemo, useRef} from 'react';
import {useThemeType} from '@gravity-ui/uikit';
import type {MinimalValidConfig, RawSerieData} from '@gravity-ui/yagr';
import Yagr from '@gravity-ui/yagr';

import {type CpuSample} from './cpu-usage-stream';

type CpuUsageChartProps = {
    samples: CpuSample[];
    endTimestamp: number;
};

const DAY_MS = 24 * 60 * 60 * 1000;
const CPU_SERIES_ID = 'cpu-usage';

export function CpuUsageChart({samples, endTimestamp}: CpuUsageChartProps) {
    const theme = useThemeType();
    const containerRef = useRef<HTMLDivElement | null>(null);
    const chartRef = useRef<Yagr<MinimalValidConfig> | null>(null);

    const timeline = useMemo(() => samples.map((sample) => sample.timestamp), [samples]);
    const values = useMemo(() => samples.map((sample) => sample.value), [samples]);
    const axesConfig = useMemo(
        () => createAxesConfig(endTimestamp - DAY_MS),
        [endTimestamp],
    );

    const initialConfig = useMemo(
        (): MinimalValidConfig => ({
            chart: {
                series: {type: 'area'},
                appearance: {theme: 'light'},
            },
            timeline,
            series: [createCpuSeries(values)],
            axes: axesConfig,
            scales: {y: {type: 'linear', min: 0, max: 1}},
            cursor: {snapToValues: 'closest'},
        }),
        [axesConfig, endTimestamp, timeline, values],
    );

    useEffect(() => {
        if (!containerRef.current) {
            return undefined;
        }

        const chart = new Yagr<MinimalValidConfig>(containerRef.current, initialConfig);
        chartRef.current = chart;

        return () => {
            chart.dispose();
            chartRef.current = null;
        };
    }, [initialConfig]);

    useEffect(() => {
        const chart = chartRef.current;

        if (!chart || chart.config.timeline === timeline) {
            return;
        }

        chart.batch(() => {
        chart.setSeries(timeline, [createCpuSeries(values)], {incremental: false});
        });
    }, [endTimestamp, timeline, values]);

    useEffect(() => {
        const chart = chartRef.current;
        const yagrTheme = theme === 'dark' ? 'dark' : 'light';

        chart?.setTheme(yagrTheme);
    }, [theme]);

    return <div ref={containerRef} className="cpu-usage-chart" />;
}

function createCpuSeries(values: number[]): RawSerieData {
    return {
        id: CPU_SERIES_ID,
        name: 'Загрузка CPU',
        type: 'area',
        data: values,
        color: 'var(--g-color-data-flowchart-region-success-fill)',

        formatter: (value) => `${Math.round((Number(value) || 0) * 100)}%`,
        precision: 2,
    };
}

function createAxesConfig(minTimestamp: number): MinimalValidConfig['axes'] {
    const timeFormatter = new Intl.DateTimeFormat('ru-RU', {
        hour: '2-digit',
        minute: '2-digit',
        timeZone: 'UTC',
    });

    return {
        x: {
            scale: 'x',

            values: (_chart, ticks) => ticks.map((value) => timeFormatter.format(value)),
            grid: {show: true, stroke: 'var(--g-color-line-generic)'},
            labelSize: 11,
            stroke: 'var(--g-color-text-hint)',
        },
        y: {
            scale: 'y',

            values: (_chart, ticks) => ticks.map((value) => `${Math.round(value * 100)}%`),
            grid: {show: true, stroke: 'var(--g-color-line-generic)'},
            stroke: 'var(--g-color-text-hint)',
        },
    };
}
import {useEffect, useMemo, useState} from 'react';
import {Card, Text} from '@gravity-ui/uikit';

import {CpuUsageChart} from './CpuUsageChart';
import {createCpuUsageSource, createHistoricalCpuData, type CpuSample} from './cpu-usage-stream';

const MAX_SAMPLE_COUNT = 17_280;

export function App() {
    const [samples, setSamples] = useState<CpuSample[]>(() => createHistoricalCpuData(Date.now()));
    const [endTimestamp, setEndTimestamp] = useState(() => Date.now());

    useEffect(() => {
        const cpuSource = createCpuUsageSource();
        const unsubscribe = cpuSource.subscribe((sample) => {
            setSamples((previousSamples) => {
                const nextSamples = [...previousSamples, sample];

                if (nextSamples.length > MAX_SAMPLE_COUNT) {
                    nextSamples.splice(0, nextSamples.length - MAX_SAMPLE_COUNT);
                }

                return nextSamples;
            });
            setEndTimestamp(sample.timestamp);
        });

        return () => {
            unsubscribe();
        };
    }, []);

    const lastSample = useMemo(
        () => samples[samples.length - 1],
        [samples],
    );

    return (
        <main className="monitoring-page">
            <Card view="filled" className="monitoring-card">
                <Text variant="header-2">CPU</Text>
                <Text variant="body-1" color="secondary">
                    Загрузка за последние сутки{lastSample ? ` · ${formatCpuValue(lastSample.value)}` : ''}
                </Text>
                <div className="cpu-chart-container">
                    <CpuUsageChart samples={samples} endTimestamp={endTimestamp} />
                </div>
            </Card>
        </main>
    );
}

function formatCpuValue(value: number): string {
    return new Intl.NumberFormat('ru-RU', {
        style: 'percent',
        maximumFractionDigits: 1,
    }).format(value);
}
export type CpuSample = {
    timestamp: number;
    value: number;
};

type CpuUsageSource = {
    subscribe: (listener: (sample: CpuSample) => void) => () => void;
};

const DAY_MS = 24 * 60 * 60 * 1000;
const SAMPLE_INTERVAL_MS = 5_000;
const SAMPLE_COUNT = DAY_MS / SAMPLE_INTERVAL_MS;

function generateSample(previousValue: number, timestamp: number): CpuSample {
    const hour = new Date(timestamp).getUTCHours();
    const dailyLoad = 0.38 + Math.sin(((hour - 7) / 24) * Math.PI * 2) * 0.19;
    const drift = (previousValue - dailyLoad) * 0.92;
    const noise = (Math.random() - 0.5) * 0.12;

    return {
        timestamp,
        value: Math.min(1, Math.max(0, drift + dailyLoad + noise)),
    };
}

export function createCpuUsageSource(): CpuUsageSource {
    const listeners = new Set<(sample: CpuSample) => void>();
    let lastTimestamp = Date.now() - SAMPLE_INTERVAL_MS;
    let lastValue = generateSample(0.55, lastTimestamp).value;

    const timer = setInterval(() => {
        lastTimestamp += SAMPLE_INTERVAL_MS;
        lastValue = generateSample(lastValue, lastTimestamp).value;

        const sample = {timestamp: lastTimestamp, value: lastValue};
        listeners.forEach((listener) => listener(sample));
    }, SAMPLE_INTERVAL_MS);

    return {
        subscribe(listener) {
            listeners.add(listener);

            return () => {
                listeners.delete(listener);
            };
        },
    };
}

export function createHistoricalCpuData(now: number): CpuSample[] {
    const samples: CpuSample[] = [];
    const startTime = Math.floor(now / SAMPLE_INTERVAL_MS) * SAMPLE_INTERVAL_MS - DAY_MS;
    let previousValue = 0.55;

    for (let index = 0; index < SAMPLE_COUNT; index += 1) {
        const timestamp = startTime + index * SAMPLE_INTERVAL_MS;
        const sample = generateSample(previousValue, timestamp);
        samples.push(sample);
        previousValue = sample.value;
    }

    return samples;
}

export const cpuUsageSampleIntervalMs = SAMPLE_INTERVAL_MS;
